        [Test]
        public void FixtureA_WithoutAiKey_EveryTickHashAsRecorded()
        {
            Assert.That(AHashes.Length, Is.EqualTo(601));
            var each = new List<ulong>();
            L4.HashRun(L4.A(10, null), 600, each);
            for (int t = 0; t <= 600; t++) Assert.That(each[t], Is.EqualTo(AHashes[t]), "tick " + t);
        }
